    ('Tesla', 'Model 3', 2026::integer, 'Performance', 'performance', null, null::numeric, 'electric', 'automatic', null, 'Sedan', 5::integer, 920::integer),
    ('Tesla', 'Model Y', 2022::integer, 'Rear-Wheel Drive', 'rear-wheel-drive', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 930::integer),
    ('Tesla', 'Model Y', 2023::integer, 'Rear-Wheel Drive', 'rear-wheel-drive', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 930::integer),
    ('Tesla', 'Model Y', 2024::integer, 'Rear-Wheel Drive', 'rear-wheel-drive', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 930::integer),
    ('Tesla', 'Model Y', 2025::integer, 'Rear-Wheel Drive', 'rear-wheel-drive', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 930::integer),
    ('Tesla', 'Model Y', 2026::integer, 'Rear-Wheel Drive', 'rear-wheel-drive', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 930::integer),
    ('Tesla', 'Model Y', 2022::integer, 'Long Range', 'long-range', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 940::integer),
    ('Tesla', 'Model Y', 2023::integer, 'Long Range', 'long-range', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 940::integer),
    ('Tesla', 'Model Y', 2024::integer, 'Long Range', 'long-range', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 940::integer),
    ('Tesla', 'Model Y', 2025::integer, 'Long Range', 'long-range', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 940::integer),
    ('Tesla', 'Model Y', 2026::integer, 'Long Range', 'long-range', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 940::integer),
    ('Tesla', 'Model Y', 2022::integer, 'Performance', 'performance', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 950::integer),
    ('Tesla', 'Model Y', 2023::integer, 'Performance', 'performance', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 950::integer),
    ('Tesla', 'Model Y', 2024::integer, 'Performance', 'performance', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 950::integer),
    ('Tesla', 'Model Y', 2025::integer, 'Performance', 'performance', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 950::integer),
    ('Tesla', 'Model Y', 2026::integer, 'Performance', 'performance', null, null::numeric, 'electric', 'automatic', null, 'SUV', 5::integer, 950::integer)
) as x(
  brand, model, year, name, slug, engine, engine_capacity, fuel_type, transmission,
  drivetrain, body_type, seating_capacity, sort_order
)
join public.vehicle_makes mk on mk.name = x.brand
join public.vehicle_models vm on vm.make_id = mk.id and vm.name = x.model
join public.vehicle_model_years my
  on my.model_id = vm.id and my.year = x.year and my.market = 'UAE'
on conflict (model_year_id, slug) do update set
  name = excluded.name,
  engine = coalesce(excluded.engine, public.vehicle_variants.engine),
  engine_capacity = coalesce(excluded.engine_capacity, public.vehicle_variants.engine_capacity),
  fuel_type = coalesce(excluded.fuel_type, public.vehicle_variants.fuel_type),
  transmission = coalesce(excluded.transmission, public.vehicle_variants.transmission),
  drivetrain = coalesce(excluded.drivetrain, public.vehicle_variants.drivetrain),
  body_type = coalesce(excluded.body_type, public.vehicle_variants.body_type),
  seating_capacity = coalesce(excluded.seating_capacity, public.vehicle_variants.seating_capacity),
  sort_order = excluded.sort_order,
  is_active = true,
  updated_at = timezone('utc', now());


